import json
import re

async def explore(browser, name, url):
    try:
        page = await browser.new_page()
        await page.goto(url, wait_until='domcontentloaded', timeout=15000)
        await asyncio.sleep(3)

        title = await page.title()
        text = await page.evaluate('() => document.body.innerText')

        # Find paper/forum links
        links_data = await page.evaluate('''
            () => {
                const links = Array.from(document.querySelectorAll('a'));
                return links.filter(l => {
                    const href = (l.getAttribute('href') || '').trim();
                    const text = (l.textContent || '').trim();
                    return href.includes('/group?id=') || href.includes('/forum') || href.includes('paper');
                }).slice(0, 20).map(l => ({
                    href: l.getAttribute('href'),
                    text: (l.textContent || '').trim()
                }));
            }
        ''')

        # Print content
        lines = [l.strip() for l in text.split('\n') if l.strip() and len(l.strip()) > 5]
        print(f'\n=== {name} ===')
        print(f'URL: {url}')
        print(f'Title: {title}')

        for link in links_data:
            if link['text']:
                print(f'  LINK: {link["text"][:80]} -> {link["href"]}')

        # Print first 20 content lines  
        for line in lines[:20]:
            print(f'  TXT: {line[:150]}')

        await page.close()
    except Exception as e:
        print(f'{name}: Error - {str(e)[:100]}')

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)

        await explore(browser, 'ICLR 2025 Program', 'https://iclr.cc/Conferences/2025/Program')
        await asyncio.sleep(1)

        await explore(browser, 'NeurIPS 2024 Welcome', 'https://neurips.cc/Conferences/2024/Welcome')
        await asyncio.sleep(1)

        await explore(browser, 'ICML 2024', 'https://icml.cc/virtual/2024/index.html')
        await asyncio.sleep(1)

        await browser.close()

asyncio.run(main())
